  "support.faq.mentor.a": "Mentorlar səhifəsində ixtisasa, görüş formatına və dilə görə süz, uyğun mentora birbaşa müraciət göndər. İstəsən qısa qeyd əlavə et ki, nədə kömək lazım olduğunu bilsin. Müraciət mentorun özünə çatır; qəbul etsə, iş panelindən ona yaza bilərsən.",
  "support.faq.response.q": "Nə vaxt cavab gözləməliyəm?",
  "support.faq.response.a": "Dəstək sorğularına adətən bir iş günü ərzində cavab veririk. Mentorluq müraciətinə isə mentorun özü cavab verir — vəziyyəti Mentorlar səhifəsində və iş panelində görünür.",
  "support.faq.events.q": "Tədbir qeydiyyatımı dəyişə bilərəm?",
  "support.faq.events.a": "Qeydiyyatı özün geri çəkə bilərsən: tədbiri aç və qeydiyyatını geri çək — yer boşalır və başqası yazıla bilər. Qeydiyyatı başqa birinə ötürmək mümkün deyil; o, özü qeydiyyatdan keçməlidir.",
  "support.faq.safety.q": "EduRate icmada təhlükəsizliyi necə qoruyur?",
  "support.faq.safety.a": "Kiməsə yalnız o, əlaqə sorğunu qəbul etdikdən sonra yaza bilərsən. Söhbətdə istənilən istifadəçini bloklaya və ya şikayət edə bilərsən; şikayətlər moderasiya komandasına düşür və orada nəzərdən keçirilir.",
