  "club.loadError.back": "Bütün klublar",
  "legal.eyebrow": "Hüquqi məlumat · {date}",
  "legal.privacy.title": "Məxfilik siyasəti",
  "legal.privacy.lead": "EduRate müstəqil tələbə pilotudur; Qarabağ Universitetinin rəsmi informasiya sistemi deyil.",
  "legal.privacy.s1.title": "Operator və pilot statusu",
  "legal.privacy.s1.body": "EduRate tədris və təqdimat məqsədli müstəqil pilot layihədir. Operatorun hüquqi adı və rəsmi əlaqə ünvanı təsdiqlənmədən platforma rəsmi universitet xidməti kimi təqdim edilmir.",
  "legal.privacy.s2.title": "Toplanan məlumatlar",
  "legal.privacy.s2.body": "Hesab və profil məlumatları, profil/klub/elan şəkilləri, tədbir və klub iştirakları, müəllim qiymətləndirmələri, mentorluq müraciətləri, dəstək biletləri, əlaqələr, mesajlar və təhlükəsizlik qeydləri emal edilə bilər.",
  "legal.privacy.s3.title": "Məqsəd və təminatçılar",
  "legal.privacy.s3.body": "Məlumatlar xidmətin göstərilməsi, hesabın qorunması, moderasiya və xəta araşdırması üçün istifadə olunur. Hosting və məlumat bazası xidmətləri Vercel və Render, şəkillərin təhlükəsiz emalı və çatdırılması isə Cloudinary və onların infrastruktur təminatçıları üzərindən işləyə bilər.",
  "legal.privacy.s4.title": "Saxlanma və hüquqların",
  "legal.privacy.s4.body": "Hesabın, məlumatlarının surətinin, düzəlişin və silinmənin tələb edilməsi mümkündür. Şikayət edilmiş məzmun 180 günədək, təhlükəsizlik qeydləri 90 günədək, admin audit qeydləri 365 günədək saxlanıla bilər; hüquqi öhdəlik olduqda müddət uzadıla bilər.",
  "legal.privacy.s5.title": "Əlaqə",
  "legal.privacy.s5.before": "Məxfilik, məlumat düzəlişi və ya silinmə sorğusu üçün ",
  "legal.privacy.s5.link": "ictimai dəstək formasından",
  "legal.privacy.s5.after": " istifadə et. Bu mətn hüquqşünas təsdiqinə təqdim edilməlidir.",
  "legal.terms.title": "İstifadə şərtləri",
  "legal.terms.lead": "EduRate müstəqil pilotdur və universitetin rəsmi informasiya sistemi deyil.",
  "legal.terms.s1.title": "Uyğunluq və hesab",
  "legal.terms.s1.body": "İstifadəçi doğru hesab məlumatı təqdim etməli, öz sessiyasını qorumalı və başqa şəxsin kimliyindən istifadə etməməlidir. Yetkinlik yaşına çatmayan istifadəçi qanuni nümayəndəsinin razılığı ilə istifadə etməlidir.",
  "legal.terms.s2.title": "Rəylər",
  "legal.terms.s2.body": "Müəllim rəyi yalnız şəxsi tədris təcrübəsinə və göstərilən pedaqoji meyarlara əsaslanmalıdır. Təhqir, böhtan, ayrı-seçkilik və şəxsi məlumat paylaşmaq qadağandır. Müəllim rəyə etiraz və yenidən baxılma tələb edə bilər.",
  "legal.terms.s3.title": "Mesaj və icma qaydaları",
  "legal.terms.s3.body": "Təhdid, təqib, spam və icazəsiz şəxsi məlumat paylaşımı qadağandır. İstifadəçi bloklama və şikayət vasitələrindən istifadə edə bilər. Mesajlaşma end-to-end şifrələnmiş xidmət kimi təqdim edilmir.",
  "legal.terms.s4.title": "Şəkil və müəllif hüquqları",
  "legal.terms.s4.body": "İstifadəçi yalnız paylaşmaq hüququna malik olduğu şəkli yükləyə bilər. Açıq-saçıq, zorakı, təhqiredici, saxta kimlik yaradan, zərərli və ya başqa şəxsin məxfiliyini pozan şəkillər qadağandır; belə məzmun xəbərdarlıq edilmədən silinə və hesab məhdudlaşdırıla bilər.",
  "legal.terms.s5.title": "Moderasiya və apellyasiya",
  "legal.terms.s5.body": "Qayda pozuntusu olduqda məzmun məhdudlaşdırıla, hesab dayandırıla və sübut audit məqsədi ilə saxlanıla bilər. Qərarla bağlı dəstək forması vasitəsilə yenidən baxılma istənilə bilər.",
  "legal.terms.s6.title": "Məhdudiyyət",
  "legal.terms.s6.body": "Pilot məlumatları rəsmi universitet qərarı, akademik arayış və ya hüquqi məsləhət hesab edilmir. Bu şərtlər production istifadəsindən əvvəl hüquqşünas tərəfindən təsdiqlənməlidir.",
