  "support.eyebrow": "Help centre",
  "support.title": "Support",
  "support.faqTitle": "Frequently asked questions",
  "support.faqCount": "Answers: {count}",
  "support.faq.mentor.q": "How do I choose a mentor?",
  "support.faq.mentor.a": "On the Mentors page, filter by field, meeting format and language, and send a request straight to the mentor who fits. You can add a short note so they know what you need help with. The request goes to the mentor directly; if they accept, you can message them from your workspace.",
  "support.faq.response.q": "When should I expect a reply?",
  "support.faq.response.a": "We usually answer support requests within one working day. Mentorship requests are answered by the mentor — you can see their status on the Mentors page and in your workspace.",
  "support.faq.events.q": "Can I change my event registration?",
  "support.faq.events.a": "You can withdraw it yourself: open the event and withdraw your registration — the place is freed for someone else. A registration cannot be transferred to another person; they need to register themselves.",
  "support.faq.safety.q": "How does EduRate keep the community safe?",
  "support.faq.safety.a": "You can only message someone after they accept your connection request. In a chat you can block or report anyone; reports go to the moderation team for review.",
