  "legal.eyebrow": "Legal information · {date}",
  "legal.privacy.title": "Privacy policy",
  "legal.privacy.lead": "EduRate is an independent student pilot; it is not an official information system of Karabakh University.",
  "legal.privacy.s1.title": "Operator and pilot status",
  "legal.privacy.s1.body": "EduRate is an independent pilot project for teaching and presentation purposes. Until the operator's legal name and official contact address are confirmed, the platform is not presented as an official university service.",
  "legal.privacy.s2.title": "Data collected",
  "legal.privacy.s2.body": "Account and profile details, profile, club and announcement images, event and club participation, teacher ratings, mentorship applications, support tickets, connections, messages and security logs may be processed.",
  "legal.privacy.s3.title": "Purpose and providers",
  "legal.privacy.s3.body": "Data is used to provide the service, protect accounts, moderate content and investigate errors. Hosting and database services may run on Vercel and Render, and secure image processing and delivery on Cloudinary, together with their infrastructure providers.",
  "legal.privacy.s4.title": "Retention and your rights",
  "legal.privacy.s4.body": "You can request access to your account, a copy of your data, its correction or deletion. Reported content may be kept for up to 180 days, security logs for up to 90 days and admin audit logs for up to 365 days; the period may be extended where there is a legal obligation.",
  "legal.privacy.s5.title": "Contact",
  "legal.privacy.s5.before": "For privacy, data correction or deletion requests, use the ",
  "legal.privacy.s5.link": "public support form",
  "legal.privacy.s5.after": ". This text must be submitted for legal review.",
  "legal.terms.title": "Terms of use",
  "legal.terms.lead": "EduRate is an independent pilot and not the university's official information system.",
  "legal.terms.s1.title": "Eligibility and account",
  "legal.terms.s1.body": "Users must provide accurate account details, protect their own session and must not use another person's identity. A minor must use the platform with the consent of their legal representative.",
  "legal.terms.s2.title": "Reviews",
  "legal.terms.s2.body": "A teacher review must be based only on personal learning experience and the stated teaching criteria. Insults, defamation, discrimination and sharing personal data are prohibited. A teacher may object to a review and ask for it to be reconsidered.",
  "legal.terms.s3.title": "Messaging and community rules",
  "legal.terms.s3.body": "Threats, harassment, spam and sharing personal data without permission are prohibited. Users can block and report. Messaging is not offered as an end-to-end encrypted service.",
  "legal.terms.s4.title": "Images and copyright",
  "legal.terms.s4.body": "Users may only upload images they have the right to share. Sexually explicit, violent, offensive, impersonating, harmful or privacy-violating images are prohibited; such content may be removed without warning and the account restricted.",
  "legal.terms.s5.title": "Moderation and appeals",
  "legal.terms.s5.body": "If the rules are broken, content may be restricted, the account suspended and evidence kept for audit purposes. A reconsideration of the decision can be requested through the support form.",
  "legal.terms.s6.title": "Limitation",
  "legal.terms.s6.body": "Pilot data is not an official university decision, an academic certificate or legal advice. These terms must be approved by a lawyer before production use.",
  // --- Səhifə başlıqları ---
