  "support.eyebrow": "Центр помощи",
  "support.title": "Поддержка",
  "support.faqTitle": "Частые вопросы",
  "support.faqCount": "Ответов: {count}",
  "support.faq.mentor.q": "Как выбрать ментора?",
  "support.faq.mentor.a": "На странице «Менторы» отфильтруй по направлению, формату встреч и языку и отправь запрос подходящему ментору напрямую. Можно добавить короткую заметку, чтобы ментор знал, с чем нужна помощь. Запрос приходит самому ментору; если он его примет, написать ему можно из рабочей панели.",
  "support.faq.response.q": "Когда ждать ответа?",
  "support.faq.response.a": "На запросы в поддержку мы обычно отвечаем в течение одного рабочего дня. На запрос о наставничестве отвечает сам ментор — статус виден на странице «Менторы» и в рабочей панели.",
  "support.faq.events.q": "Можно ли изменить регистрацию на мероприятие?",
  "support.faq.events.a": "Отменить регистрацию можно самостоятельно: открой мероприятие и отзови регистрацию — место освободится для другого. Передать регистрацию другому человеку нельзя: ему нужно зарегистрироваться самому.",
  "support.faq.safety.q": "Как EduRate обеспечивает безопасность сообщества?",
  "support.faq.safety.a": "Написать человеку можно только после того, как он примет запрос на связь. В чате любого пользователя можно заблокировать или пожаловаться на него; жалобы попадают к команде модерации на рассмотрение.",
