  "legal.eyebrow": "Правовая информация · {date}",
  "legal.privacy.title": "Политика конфиденциальности",
  "legal.privacy.lead": "EduRate — независимый студенческий пилотный проект, а не официальная информационная система Карабахского университета.",
  "legal.privacy.s1.title": "Оператор и статус пилотного проекта",
  "legal.privacy.s1.body": "EduRate — независимый пилотный проект в учебных и демонстрационных целях. Пока юридическое название оператора и официальный контактный адрес не подтверждены, платформа не представляется как официальный сервис университета.",
  "legal.privacy.s2.title": "Собираемые данные",
  "legal.privacy.s2.body": "Могут обрабатываться данные аккаунта и профиля, изображения профиля, клубов и объявлений, участие в мероприятиях и клубах, оценки преподавателей, заявки на менторство, обращения в поддержку, связи, сообщения и журналы безопасности.",
  "legal.privacy.s3.title": "Цели и поставщики",
  "legal.privacy.s3.body": "Данные используются для работы сервиса, защиты аккаунтов, модерации и расследования ошибок. Хостинг и базы данных могут работать на Vercel и Render, а безопасная обработка и доставка изображений — через Cloudinary и их инфраструктурных поставщиков.",
  "legal.privacy.s4.title": "Хранение и ваши права",
  "legal.privacy.s4.body": "Вы можете запросить доступ к аккаунту, копию своих данных, их исправление или удаление. Материалы, на которые поступили жалобы, могут храниться до 180 дней, журналы безопасности — до 90 дней, журналы аудита администраторов — до 365 дней; при наличии правовых обязательств срок может быть продлён.",
  "legal.privacy.s5.title": "Связь",
  "legal.privacy.s5.before": "Для запросов о конфиденциальности, исправлении или удалении данных используйте ",
  "legal.privacy.s5.link": "общедоступную форму поддержки",
  "legal.privacy.s5.after": ". Этот текст должен пройти проверку юристом.",
  "legal.terms.title": "Условия использования",
  "legal.terms.lead": "EduRate — независимый пилотный проект, а не официальная информационная система университета.",
  "legal.terms.s1.title": "Допуск и аккаунт",
  "legal.terms.s1.body": "Пользователь должен указывать достоверные данные, защищать свою сессию и не использовать чужую личность. Несовершеннолетний пользуется платформой с согласия законного представителя.",
  "legal.terms.s2.title": "Отзывы",
  "legal.terms.s2.body": "Отзыв о преподавателе должен основываться только на личном опыте обучения и указанных педагогических критериях. Оскорбления, клевета, дискриминация и публикация личных данных запрещены. Преподаватель может оспорить отзыв и запросить его повторное рассмотрение.",
  "legal.terms.s3.title": "Правила сообщений и сообщества",
  "legal.terms.s3.body": "Угрозы, преследование, спам и распространение личных данных без разрешения запрещены. Пользователь может блокировать и отправлять жалобы. Переписка не предоставляется как сервис со сквозным шифрованием.",
  "legal.terms.s4.title": "Изображения и авторские права",
  "legal.terms.s4.body": "Пользователь может загружать только изображения, которыми вправе делиться. Откровенные, жестокие, оскорбительные, выдающие себя за другого, вредоносные или нарушающие чужую конфиденциальность изображения запрещены; такой контент может быть удалён без предупреждения, а аккаунт — ограничен.",
  "legal.terms.s5.title": "Модерация и обжалование",
  "legal.terms.s5.body": "При нарушении правил контент может быть ограничен, аккаунт приостановлен, а доказательства сохранены для аудита. Пересмотр решения можно запросить через форму поддержки.",
  "legal.terms.s6.title": "Ограничения",
  "legal.terms.s6.body": "Данные пилотного проекта не являются официальным решением университета, академической справкой или юридической консультацией. Эти условия должны быть утверждены юристом до промышленного использования.",
  // --- Səhifə başlıqları ---
